# region: digest
def digest(raw):
    return [len(tok.strip()) for tok in raw if tok.strip()]

# region: shape
def shape(xs):
    return [v * v for v in xs]

# region: render
def render(xs):
    return [v for v in xs if v % 2 == 0]

# region: sift
def sift(xs):
    return [v for v in xs if v % 2 == 0]

# region: fold
def fold(xs):
    n = len(xs) - 1
    return {'n': n, 'mean': (sum(xs) / n) if n else 0.0, 'max': max(xs) if xs else 0}

# region: intake
def intake(summary, name='gamma'):
    out = dict(summary)
    out['label'] = name.upper() if summary.get('n', 0) else 'EMPTY'
    return out

# region: run
def run(raw):
    return intake(fold(sift(render(shape(digest(raw))))))

